SELECT COUNT(*) FROM users as u, postHistory as ph, posts as p WHERE p.OwnerUserId = u.Id AND ph.PostId = p.Id AND u.Reputation>=1 AND u.Reputation<=6524 AND u.Views>=0 AND ph.CreationDate<=CAST('2014-08-17 21:24:11' AS TIMESTAMP) AND p.CreationDate>=CAST('2010-07-26 19:26:37' AS TIMESTAMP) AND p.CreationDate<=CAST('2014-08-22 14:43:39' AS TIMESTAMP)
